
.opening-form {
  --bg-0: #0b0c0f;
  --bg-1: #151820;
  --glass: rgba(255, 255, 255, 0.06);
  --glass-strong: rgba(255, 255, 255, 0.1);
  --line: rgba(255, 255, 255, 0.14);
  --text: rgba(255, 255, 255, 0.92);
  --text-soft: rgba(255, 255, 255, 0.68);
  --text-faint: rgba(255, 255, 255, 0.48);
  --accent: #c7ccd4;
  --danger: #ff6b6b;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC', 'Noto Sans SC', sans-serif;
  color: var(--text);
  background:
    radial-gradient(1200px 700px at 8% -10%, rgba(255, 255, 255, 0.12), transparent 60%),
    radial-gradient(900px 500px at 108% 110%, rgba(255, 255, 255, 0.08), transparent 60%),
    linear-gradient(160deg, var(--bg-0) 0%, var(--bg-1) 100%);

  &.light {
    --bg-0: #eef1f6;
    --bg-1: #dee3ea;
    --glass: rgba(255, 255, 255, 0.62);
    --glass-strong: rgba(255, 255, 255, 0.82);
    --line: rgba(17, 24, 39, 0.12);
    --text: rgba(17, 24, 39, 0.92);
    --text-soft: rgba(17, 24, 39, 0.68);
    --text-faint: rgba(17, 24, 39, 0.48);
    --accent: #3a4352;
    --danger: #dc3c3c;
  }
}

.book-container {
  width: 100%;
  max-width: 880px;
  min-height: 690px;
  position: relative;
  border-radius: 28px;
  overflow: hidden;
  background: var(--glass);
  border: 1px solid var(--line);
  box-shadow:
    0 30px 80px rgba(0, 0, 0, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(20px) saturate(140%);

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.12) 0%,
      rgba(255, 255, 255, 0.02) 24%,
      rgba(255, 255, 255, 0.05) 100%
    );
  }

  &.flipping .book-page {
    animation: pageSwitch 0.24s cubic-bezier(0.22, 1, 0.36, 1);
  }
}

@keyframes pageSwitch {
  0% {
    opacity: 0.65;
    transform: translateY(8px) scale(0.99);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.book-page {
  position: relative;
  width: 100%;
  min-height: 690px;
  overflow: hidden;
}

.cover-page {
  display: grid;
  place-items: center;
  padding: 64px 48px;
  text-align: center;
}

.book-cover {
  width: 100%;
  max-width: 460px;
}

.cover-decoration {
  border-radius: 24px;
  padding: 22px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(8px);
}

.cover-border {
  border-radius: 18px;
  border: 1px solid var(--line);
  padding: 18px;
}

.cover-inner {
  border-radius: 14px;
  padding: 40px 22px;
  background: rgba(255, 255, 255, 0.03);
}

.book-icon {
  font-size: 58px;
  color: var(--accent);
  margin-bottom: 20px;
}

.book-title {
  margin: 0 0 8px;
  font-size: 40px;
  line-height: 1.1;
  letter-spacing: 0.02em;
  font-weight: 700;
}

.book-subtitle {
  margin: 0 0 20px;
  font-size: 12px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-faint);
}

.cover-divider {
  width: 72%;
  height: 1px;
  margin: 0 auto 18px;
  background: linear-gradient(90deg, transparent, var(--line), transparent);
}

.book-desc {
  margin: 0 0 30px;
  font-size: 15px;
  color: var(--text-soft);
}

.start-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 34px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.22) 0%,
    rgba(255, 255, 255, 0.08) 100%
  );
  color: var(--text);
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;

  &:hover {
    transform: translateY(-1px);
    border-color: rgba(255, 255, 255, 0.28);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.18);
  }

  &:active {
    transform: scale(0.98);
  }
}

.cover-tools {
  margin-top: 22px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

.cover-tool-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-soft);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.18s ease;

  &:hover {
    color: var(--text);
    border-color: rgba(255, 255, 255, 0.26);
    background: rgba(255, 255, 255, 0.08);
  }
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.library-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 14px;
}

.library-toolbar--characters {
  margin-bottom: 16px;
}

.library-toolbar-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-soft);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s ease;

  &:hover {
    color: var(--text);
    border-color: rgba(255, 255, 255, 0.24);
  }
}

.custom-rule-actions {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  flex-shrink: 0;
}

.library-mini-btn {
  width: 30px;
  height: 30px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-faint);
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: all 0.18s ease;

  &:hover {
    color: var(--accent);
    border-color: rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.06);
  }
}

.confirm-presets-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-bottom: 18px;
}

.preset-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-soft);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s ease;

  &:hover {
    color: var(--text);
    border-color: rgba(255, 255, 255, 0.26);
  }
}

.opening-dialog-panel--wide {
  max-width: 520px;
  max-height: min(80vh, 640px);
  display: flex;
  flex-direction: column;
}

.opening-dialog-input {
  width: 100%;
  margin-bottom: 16px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
  font-size: 14px;

  &:focus {
    outline: none;
    border-color: rgba(255, 255, 255, 0.3);
  }
}

.opening-dialog-empty {
  margin: 8px 0 16px;
  padding: 20px;
  text-align: center;
  font-size: 14px;
  color: var(--text-faint);
  border-radius: 14px;
  border: 1px dashed var(--line);
}

.opening-dialog-list {
  list-style: none;
  margin: 0 0 16px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.opening-dialog-list--scroll {
  overflow-y: auto;
  flex: 1;
  min-height: 0;
  max-height: 360px;
  padding-right: 4px;
}

.opening-dialog-list-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.04);
}

.opening-dialog-list-item--stack {
  flex-direction: column;
}

.opening-dialog-list-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.opening-dialog-list-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.opening-dialog-list-meta {
  font-size: 12px;
  color: var(--text-faint);
}

.opening-dialog-list-preview {
  font-size: 12px;
  line-height: 1.45;
  color: var(--text-soft);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.opening-dialog-list-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  flex-shrink: 0;
}

.opening-dialog-list-item--stack .opening-dialog-list-actions {
  align-self: flex-end;
}

.content-page {
  display: grid;
  grid-template-rows: auto 1fr;
}

.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 28px;
  border-bottom: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.02);
}

.nav-btn {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.02);
  color: var(--text-soft);
  cursor: pointer;
  transition: all 0.18s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  &:hover {
    color: var(--text);
    border-color: rgba(255, 255, 255, 0.28);
    transform: translateY(-1px);
  }

  &:active {
    transform: scale(0.96);
  }

  &.placeholder {
    visibility: hidden;
  }
}

.page-number {
  color: var(--text-faint);
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 600;
}

.page-content {
  padding: 28px 30px 30px;
  overflow-y: auto;
  max-height: 610px;
}

.chapter-title {
  margin: 0 0 8px;
  font-size: 30px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.chapter-desc {
  margin: 0 0 24px;
  color: var(--text-soft);
  font-size: 14px;
}

.scene-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 24px;
}

.scene-card,
.rule-item,
.custom-rule-item,
.char-card,
.custom-rules-section,
.character-form,
.summary-section {
  border-radius: 18px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.04);
  transition: transform 0.2s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.2s ease, box-shadow 0.2s ease;
}

.scene-card {
  padding: 16px;
  cursor: pointer;
  text-align: left;

  &:hover,
  &.active {
    transform: translateY(-2px);
    border-color: rgba(255, 255, 255, 0.28);
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.18);
  }

  &.active {
    background: var(--glass-strong);
  }
}

.scene-icon {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  margin-bottom: 10px;
  font-size: 20px;
  background: rgba(255, 255, 255, 0.1);
  color: var(--accent);
}

.scene-name {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 600;
}

.scene-desc {
  margin: 0;
  font-size: 12px;
  line-height: 1.45;
  color: var(--text-soft);
}

.custom-scene {
  margin-top: 20px;
}

.custom-label {
  display: block;
  margin-bottom: 8px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-soft);
}

.custom-textarea,
.rule-name-input,
.rule-desc-input,
.char-name-input,
.char-gender-select,
.char-desc-input {
  width: 100%;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.03);
  color: var(--text);
  font-size: 14px;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;

  &::placeholder {
    color: var(--text-faint);
  }

  &:focus {
    outline: none;
    border-color: rgba(255, 255, 255, 0.34);
    box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.08);
    background: rgba(255, 255, 255, 0.05);
  }
}

.custom-textarea,
.rule-desc-input,
.char-desc-input {
  resize: vertical;
  min-height: 86px;
}

.rules-section {
  margin-bottom: 22px;
}

.section-title {
  margin: 0 0 14px;
  font-size: 15px;
  font-weight: 700;
}

.rules-list {
  display: grid;
  gap: 10px;
}

.rule-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px;
  cursor: pointer;

  &:hover,
  &.checked {
    border-color: rgba(255, 255, 255, 0.28);
    background: var(--glass-strong);
    transform: translateY(-1px);
  }
}

.rule-checkbox {
  position: relative;
  flex-shrink: 0;

  input {
    display: none;
  }
}

.check-mark {
  width: 22px;
  height: 22px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.03);
  display: grid;
  place-items: center;
  color: var(--accent);
  transition: all 0.18s ease;

  i {
    font-size: 12px;
    opacity: 0;
    transform: scale(0.85);
    transition: all 0.18s ease;
  }

  input:checked + & {
    background: rgba(255, 255, 255, 0.16);
    border-color: rgba(255, 255, 255, 0.34);

    i {
      opacity: 1;
      transform: scale(1);
    }
  }
}

.rule-info,
.custom-rule-info,
.char-info {
  display: grid;
  gap: 4px;
  flex: 1;
  min-width: 0;
}

.rule-name,
.custom-rule-name,
.char-name {
  font-size: 14px;
  font-weight: 600;
}

.rule-desc,
.custom-rule-desc,
.char-desc {
  font-size: 12px;
  line-height: 1.45;
  color: var(--text-soft);
}

.custom-rules-section,
.character-form,
.summary-section {
  padding: 18px;
}

.custom-rule-input {
  display: grid;
  gap: 10px;
}

.form-row {
  display: flex;
  gap: 10px;
  margin-bottom: 10px;

  &:last-child {
    margin-bottom: 0;
  }
}

.char-name-input {
  flex: 1;
}

.char-gender-select {
  width: 110px;
  flex-shrink: 0;
}

.form-actions-row {
  display: flex;
  justify-content: flex-end;
}

.add-rule-btn,
.add-char-btn,
.confirm-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.2), rgba(255, 255, 255, 0.08));
  color: var(--text);
  cursor: pointer;
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;

  &:hover:not(:disabled) {
    transform: translateY(-1px);
    border-color: rgba(255, 255, 255, 0.32);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.14);
  }

  &:active:not(:disabled) {
    transform: scale(0.98);
  }
}

.add-rule-btn,
.add-char-btn {
  min-width: 112px;
  padding: 10px 18px;
  font-size: 13px;
  font-weight: 600;
}

.custom-rules-list,
.char-cards {
  margin-top: 10px;
  display: grid;
  gap: 8px;
}

.custom-rule-item,
.char-card {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px;
}

.char-avatar {
  width: 36px;
  height: 36px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.12);
  color: var(--accent);
}

.remove-btn {
  width: 30px;
  height: 30px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-faint);
  cursor: pointer;
  transition: all 0.18s ease;

  &:hover {
    color: var(--danger);
    border-color: rgba(255, 107, 107, 0.35);
    background: rgba(255, 107, 107, 0.08);
  }
}

.empty-hint {
  margin-top: 6px;
  text-align: center;
  padding: 30px 18px;
  border-radius: 18px;
  border: 1px dashed var(--line);
  color: var(--text-soft);

  i {
    display: block;
    margin-bottom: 10px;
    font-size: 36px;
    color: var(--text-faint);
  }

  p {
    margin: 0 0 6px;
    font-size: 15px;
    font-weight: 600;
    color: var(--text-soft);
  }

  span {
    font-size: 12px;
    color: var(--text-faint);
  }
}

.summary-section {
  margin: 18px 0 24px;
}

.summary-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);

  &:last-child {
    border-bottom: none;
  }
}

.summary-label {
  font-size: 13px;
  color: var(--text-soft);
}

.summary-value {
  font-size: 13px;
  font-weight: 700;
}

.confirm-actions {
  display: grid;
  justify-items: center;
}

.confirm-btn {
  min-width: 220px;
  padding: 14px 22px;
  font-size: 16px;
  font-weight: 700;

  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
  }
}

.hint-text {
  margin-top: 10px;
  color: var(--text-faint);
  font-size: 12px;
}

.chronicle-clear-btn {
  position: fixed;
  left: 20px;
  bottom: 20px;
  z-index: 50;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 14px;
  height: 44px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: var(--glass);
  color: var(--text-soft);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  backdrop-filter: blur(12px);
  transition: all 0.18s ease;

  i {
    font-size: 14px;
    opacity: 0.9;
  }

  &:hover {
    color: var(--text);
    border-color: rgba(255, 255, 255, 0.28);
    transform: translateY(-1px);
  }
}

.chronicle-dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(6px);
}

.chronicle-dialog-panel {
  width: 100%;
  max-width: 400px;
  padding: 22px 22px 18px;
  border-radius: 18px;
  border: 1px solid var(--line);
  background: var(--glass-strong);
  color: var(--text);
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(16px);
}

.chronicle-dialog-title {
  margin: 0 0 12px;
  font-size: 18px;
  font-weight: 600;
}

.chronicle-dialog-desc {
  margin: 0 0 20px;
  font-size: 14px;
  line-height: 1.55;
  color: var(--text-soft);
}

.chronicle-dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.chronicle-dialog-btn {
  min-width: 88px;
  padding: 10px 16px;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  border: 1px solid var(--line);
  background: var(--glass);
  color: var(--text);
  transition: background 0.15s ease, border-color 0.15s ease;

  &.cancel:hover {
    border-color: rgba(255, 255, 255, 0.22);
  }

  &.danger {
    border-color: rgba(220, 60, 60, 0.45);
    background: rgba(220, 60, 60, 0.18);
    color: var(--danger);

    &:hover:not(:disabled) {
      background: rgba(220, 60, 60, 0.28);
    }
  }

  &:disabled {
    opacity: 0.55;
    cursor: not-allowed;
  }
}

.opening-form.light .chronicle-dialog-btn.danger {
  border-color: rgba(220, 60, 60, 0.35);
  background: rgba(220, 60, 60, 0.12);
}

.theme-toggle {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 50;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: var(--glass);
  color: var(--text-soft);
  cursor: pointer;
  backdrop-filter: blur(12px);
  transition: all 0.18s ease;

  &:hover {
    color: var(--text);
    border-color: rgba(255, 255, 255, 0.28);
    transform: translateY(-1px);
  }
}

.page-content {
  &::-webkit-scrollbar {
    width: 8px;
  }

  &::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.2);
  }
}

@media (max-width: 900px) {
  .opening-form {
    padding: 16px;
  }

  .book-container {
    min-height: 620px;
    border-radius: 22px;
  }

  .book-page {
    min-height: 620px;
  }

  .page-content {
    padding: 20px;
    max-height: 560px;
  }

  .chapter-title {
    font-size: 24px;
  }
}

@media (max-width: 640px) {
  .scene-grid {
    grid-template-columns: 1fr;
  }

  .form-row {
    flex-direction: column;
  }

  .char-gender-select {
    width: 100%;
  }

  .theme-toggle {
    right: 12px;
    bottom: 12px;
  }

  .chronicle-clear-btn {
    left: 12px;
    bottom: 12px;
    padding: 0 12px;
    font-size: 12px;
  }
}
